const API = require("../../utils/api");Page({data:{loading:true,verified:false,error:false,roomId:"",roomName:"",errorMsg:""},onLoad(e){const roomId=e.room_id||"";if(!roomId){this.setData({loading:false,error:true,errorMsg:"缺少房间参数"});return}this.setData({roomId});API.scanRoomStatus(roomId).then(info=>{if(info.hasActiveOrder){this.setData({loading:false,verified:true,roomName:info.roomName})}else{this.setData({loading:false,error:true,errorMsg:info.message||"请联系店员开房"})}}).catch(()=>this.setData({loading:false,error:true,errorMsg:"网络异常"}))},goOrder(){wx.navigateTo({url:"/pages/scan-order/scan-order?room_id="+this.data.roomId})},goBill(){wx.navigateTo({url:"/pages/scan-bill/scan-bill?room_id="+this.data.roomId})},callStaff(){wx.showToast({title:"前台电话:020-88888888",icon:"none"})}})